<?php
require 'includes/auth_helpers.php'; require 'includes/db.php'; require_once 'includes/make_mailer.php'; require_admin($pdo);
$messages=[];
function clean_announcement_html(string $html): string {
    $dom=new DOMDocument('1.0','UTF-8'); @$dom->loadHTML('<?xml encoding="utf-8" ?><div>'.$html.'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);
    $allowed=['div','p','br','strong','b','em','i','u','ul','ol','li','a','h2','h3','blockquote'];
    $walk=function(DOMNode $node) use (&$walk,$allowed): void { for($child=$node->firstChild;$child;){$next=$child->nextSibling;if($child instanceof DOMElement){if(!in_array(strtolower($child->tagName),$allowed,true)){while($child->firstChild)$node->insertBefore($child->firstChild,$child);$node->removeChild($child);}else{foreach(iterator_to_array($child->attributes) as $attr){if($child->tagName==='a'&&$attr->name==='href'&&preg_match('#^https?://#i',$attr->value))continue;$child->removeAttribute($attr->name);}if($child->tagName==='a')$child->setAttribute('rel','noopener noreferrer');$walk($child);}}elseif(!($child instanceof DOMText)&&!($child instanceof DOMComment))$node->removeChild($child);$child=$next;} };
    $root=$dom->getElementsByTagName('div')->item(0);if(!$root)return ''; $walk($root);$out='';foreach($root->childNodes as $child)$out.=$dom->saveHTML($child);return $out;
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!csrf_check($_POST['csrf']??null))$messages[]=['kind'=>'danger','text'=>'Session expired. Refresh and try again.'];
 else{$subject=trim((string)($_POST['subject']??''));$html=clean_announcement_html((string)($_POST['body_html']??''));$text=trim(html_entity_decode(strip_tags(str_replace(['</p>','</div>','</li>','<br>','<br/>','<br />'],"\n",$html)),ENT_QUOTES|ENT_HTML5,'UTF-8'));
  if($subject===''||mb_strlen($subject)>180||$text==='')$messages[]=['kind'=>'danger','text'=>'Enter a subject and announcement content.'];
  else{$recipients=$pdo->query('SELECT email_addr FROM email_subscriptions WHERE unsubscribed_at IS NULL ORDER BY subscription_id')->fetchAll(PDO::FETCH_COLUMN);$sent=0;$failed=0;foreach($recipients as $recipient){try{if(send_notification_email((string)$recipient,$subject,$text,'announcement',$html))$sent++;else $failed++;}catch(Throwable $e){$failed++;error_log('Nomcha announcement failed: '.$e->getMessage());}}$messages[]=['kind'=>$failed?'warning':'success','text'=>"Announcement sent to {$sent} subscriber(s).".($failed?" {$failed} could not be sent.":'')];}
 }
}
$pageTitle='Announcements';require 'includes/header.php';render_toasts($messages);
?>
<main class="container py-5"><div class="mb-4"><p class="text-uppercase small fw-semibold text-secondary mb-1">Admin only</p><h1>Announcements</h1><p class="text-secondary">Create a formatted email for active Nomcha email subscribers.</p></div><form method="post" class="card card-body" id="announcement-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="mb-3"><label class="form-label" for="subject">Email subject</label><input class="form-control" id="subject" name="subject" maxlength="180" required></div><label class="form-label" for="mail-editor">Email content</label><div class="btn-toolbar gap-1 mb-2" role="toolbar" aria-label="Text formatting"><button type="button" class="btn btn-sm btn-outline-secondary" data-command="bold"><strong>B</strong></button><button type="button" class="btn btn-sm btn-outline-secondary" data-command="italic"><em>I</em></button><button type="button" class="btn btn-sm btn-outline-secondary" data-command="underline"><u>U</u></button><button type="button" class="btn btn-sm btn-outline-secondary" data-command="insertUnorderedList">Bullets</button><button type="button" class="btn btn-sm btn-outline-secondary" data-command="insertOrderedList">Numbered list</button><button type="button" class="btn btn-sm btn-outline-secondary" data-command="formatBlock" data-value="h2">Heading</button><button type="button" class="btn btn-sm btn-outline-secondary" data-link>Insert link</button></div><div class="form-control" id="mail-editor" contenteditable="true" role="textbox" aria-multiline="true" style="min-height:260px;overflow:auto"></div><input type="hidden" name="body_html" id="body-html"><p class="form-text mt-2">Formatting is cleaned before sending. Each email includes an unsubscribe link.</p><div class="border rounded p-3 bg-light mb-3"><strong>Recipients</strong><p class="mb-0 small text-secondary">Active email subscribers only. You’ll see the number sent and any failures after sending.</p></div><button class="btn btn-auth align-self-start" type="submit" onclick="document.getElementById('body-html').value=document.getElementById('mail-editor').innerHTML">Send announcement</button></form></main><script>document.querySelectorAll('[data-command]').forEach(b=>b.addEventListener('click',()=>{document.getElementById('mail-editor').focus();document.execCommand(b.dataset.command,false,b.dataset.value||null)}));document.querySelector('[data-link]').addEventListener('click',()=>{const url=prompt('Enter a full https:// link');if(url&&/^https?:\/\//i.test(url))document.execCommand('createLink',false,url)});document.getElementById('announcement-form').addEventListener('submit',()=>document.getElementById('body-html').value=document.getElementById('mail-editor').innerHTML);</script><?php require 'includes/footer.php'; ?>
